class BusPageIndex:

    def __init__(self, bus_path: Path):
        self.bus_path = bus_path
        self.path = bus_path.with_name('bus_page_index.sqlite3')
        self.connection = sqlite3.connect(self.path, timeout=30)
        self.connection.execute('PRAGMA synchronous=FULL')
        try:
            with self.connection:
                self.connection.execute('BEGIN IMMEDIATE')
                actual = SQLiteSchemaObject.read(self.connection.execute("SELECT name,sql FROM sqlite_master WHERE sql IS NOT NULL AND name NOT LIKE 'sqlite_%'"))
                schema = {name: sql for table in TypedTable.members_with(PageIndexTable) for name, sql in table.schema_objects().items()}
                if not actual:
                    for statement in schema.values():
                        self.connection.execute(statement)
                elif {row.name: row.sql for row in actual} != schema:
                    raise StaleBusPageIndexError('Bus page index requires the quiet runtime reset')
        except BaseException:
            self.connection.close()
            raise

    def __enter__(self) -> BusPageIndex:
        return self

    def __exit__(self, *_error: object) -> None:
        self.connection.close()

    @staticmethod
    def _tail(stream: BinaryIO, offset: int) -> str:
        start = max(0, offset - 4096)
        stream.seek(start)
        return sha256(stream.read(offset - start)).hexdigest()

    def sync(self) -> bool:
        """Return false for an unfinished tail, which the caller scans normally."""
        try:
            stream = self.bus_path.open('rb')
        except FileNotFoundError:
            return False
        with stream:
            stat = os.fstat(stream.fileno())
            size = stat.st_size
            if size:
                stream.seek(size - 1)
                if stream.read(1) != b'\n':
                    return False
            identity = (stat.st_dev, stat.st_ino, stat.st_mtime_ns, stat.st_ctime_ns)
            try:
                saved = BusPageSource.one(self.connection, singleton=1)
            except (ValueError, TypeError):
                saved = None
            offset = saved.offset if saved is not None else 0
            valid = saved is not None and 0 <= offset <= size and (saved.identity[:2] == identity[:2]) and (offset != size or saved.identity[2:] == identity[2:]) and (saved.tail == self._tail(stream, offset))
            if not valid:
                offset = 0
            if valid and offset == size:
                return True
            with self.connection:
                if not valid:
                    self.connection.execute(f'DELETE FROM {BusPageRow.declared_name}')
                    last_sequence = None
                else:
                    last_rows = BusPageRow.read(self.connection.execute(f'SELECT {BusPageRow._column_list(BusPageRow.columns())} FROM {BusPageRow.declared_name} ORDER BY id DESC LIMIT 1'))
                    last_sequence = last_rows[0].seq if last_rows else None
                stream.seek(offset)
                while stream.tell() < size:
                    row_offset = stream.tell()
                    raw = stream.readline()
                    if not raw.endswith(b'\n'):
                        return False
                    if not raw.strip():
                        continue
                    record = json.loads(raw)
                    if not isinstance(record, Mapping):
                        raise ValueError('JSONL bus row must be an object.')
                    from .wire_record import WireRecord
                    for message in WireRecord.public_from_wire(record).messages():
                        if last_sequence is not None and message.seq <= last_sequence:
                            raise StaleBusPageIndexError('Wire sequences are not increasing.')
                        BusPageRow(message.seq, row_offset, message.sender, message.target).insert(self.connection)
                        last_sequence = message.seq
                BusPageSource(identity, size, self._tail(stream, size)).upsert(self.connection)
            return True

    def current(self) -> bool:
        """Read-only warm-cache check; never rebuild the bus on a wake."""
        try:
            with self.bus_path.open('rb') as stream:
                stat = os.fstat(stream.fileno())
                size = stat.st_size
                if size:
                    stream.seek(size - 1)
                    if stream.read(1) != b'\n':
                        return False
                saved = BusPageSource.one(self.connection, singleton=1)
                return saved is not None and saved == BusPageSource((stat.st_dev, stat.st_ino, stat.st_mtime_ns, stat.st_ctime_ns), size, self._tail(stream, size))
        except (OSError, ValueError, TypeError, sqlite3.DatabaseError):
            return False

    def offsets(self, *, lower: int | None, upper: int | None, descending: bool, targets: frozenset[str] | None) -> Generator[BusPageRow, None, None]:
        clauses: list[str] = []
        params: list[object] = []
        if lower is not None:
            clauses.append('seq > ?')
            params.append(lower)
        if upper is not None:
            clauses.append('seq < ?')
            params.append(upper)
        if targets is not None:
            if not targets:
                return
            clauses.append('target IN (' + ','.join(('?' for _ in targets)) + ')')
            params.extend(sorted(targets))
        where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
        direction = 'DESC' if descending else 'ASC'
        query = f'SELECT {BusPageRow._column_list(BusPageRow.columns())} FROM {BusPageRow.declared_name}' + where + f' ORDER BY seq {direction}, id {direction}'
        rows = iter(BusPageRow.iterate(self.connection.execute(query, params)))
        while True:
            try:
                row = next(rows)
            except StopIteration:
                return
            except (ValueError, TypeError) as error:
                raise StaleBusPageIndexError('Indexed row has invalid fields') from error
            yield row

    @staticmethod
    def record(stream: BinaryIO, row: BusPageRow, *, max_bytes: int | None=None) -> tuple[Mapping, int]:
        stream.seek(row.offset)
        raw = stream.readline(max_bytes + 1 if max_bytes is not None else -1)
        if max_bytes is not None and len(raw) > max_bytes:
            raise OversizedIndexedBusRowError('Indexed bus row exceeds advisory byte budget.')
        try:
            record = json.loads(raw)
        except ValueError as error:
            raise StaleBusPageIndexError('Indexed bus row is invalid.') from error
        if not isinstance(record, Mapping) or int(record.get('seq', 0)) != row.seq or record.get('from') != row.sender or (record.get('to') != row.target):
            raise StaleBusPageIndexError('Indexed bus row changed.')
        return (record, len(raw))

@dataclass(frozen=True, slots=True)
class HistorySource:
    """An immutable bus/registry snapshot attached by the destination MessageBus."""
    root: str
    original_root: str
    wire_root_id: str
    bus_identity: tuple[int, int]
    size: int
    snapshot_bus_revision: tuple[int, int, int, int]
    snapshot_registry_revision: tuple[int, int, int, int]
    provenance: RegistryProvenance

    @property
    def key(self) -> str:
        return self.root

    def validate(self) -> None:
        root = Path(self.root)
        if file_revision(root / 'bus.jsonl') != self.snapshot_bus_revision or file_revision(root / 'registry.json') != self.snapshot_registry_revision:
            raise ValueError('Historical snapshot changed; restore it before browsing')

@dataclass(frozen=True, slots=True)
class MessagePageRequest:
    """Captured membership, direction and bounds for both authoritative readers."""
    scope: MessageDisplayScope
    traversal: PageTraversal
    limit: int = 100
    max_bytes: int = 256 * 1024

    def __post_init__(self):
        if self.limit <= 0:
            raise ValueError('History page limit must be positive.')
        if self.max_bytes <= 0:
            raise ValueError('History page byte budget must be positive.')

    @classmethod
    def capture(cls, scope, *, before=None, after=None, limit=100, max_bytes=256 * 1024):
        return cls(scope, PageTraversal.capture(before, after), limit, max_bytes)

    def collect(self, records: Iterator[tuple[Message, int]]) -> MessagePage:
        return self.traversal.collect(self, records)

    def read(self, log) -> MessagePage:
        with log.locked():
            try:
                with BusPageIndex(log.path) as index:
                    if index.sync():
                        return self.indexed(index, log)
            except (OSError, sqlite3.DatabaseError, StaleBusPageIndexError):
                pass
        with log._record_snapshot(need_sequence=False) as (_, records):
            return self.collect(records)

    def indexed(self, index, log) -> MessagePage:
        window = PageWindow(self.limit, self.max_bytes)
        marker = log._private_marker_unlocked()
        targets = self.scope.index_targets
        opposite = more = False
        with log.path.open('rb') as stream:
            with closing(self.traversal.opposite_offsets(index, targets)) as rows:
                for row in rows:
                    (message, _), = log._public_page_records(*index.record(stream, row), marker)
                    if self.scope.includes(message):
                        opposite = True
                        break
            with closing(self.traversal.offsets(index, targets)) as rows:
                for row in rows:
                    (message, size), = log._public_page_records(*index.record(stream, row), marker)
                    if not self.scope.includes(message):
                        continue
                    if window.full_with(size):
                        more = True
                        break
                    self.traversal.append(window, message, size)
        return self.traversal.result(window, more, opposite)

@dataclass(frozen=True)
class CertifiedSourceRead:
    """Opened resources borrowed from one canonical durability barrier."""
    path: Path
    marker: WireMetadata
    connection: sqlite3.Connection
    stream: BinaryIO
    witness: PrefixWitness

    def require_marker(self, marker: WireMetadata) -> None:
        if self.marker != marker:
            raise RelationViolationError('Original source marker changed within its lock.')

    def require_current(self) -> None:
        self.require_open_prefix()
        self.witness.require_marker(self.marker)

    def require_open_prefix(self) -> None:
        """Validate the acquired committed bytes independently of reservations.

        Acquisition already checked root and that the sealed sequence does not
        exceed the marker. A marker may reserve a later sequence before append;
        that reservation cannot change this original committed prefix.
        """
        if self.stream.closed:
            raise RelationViolationError('Certified source read has left its lock lifetime.')
        self.marker.seal.check_final(self.witness, _path(self.path))
        if file_revision(os.fstat(self.stream.fileno())) != self.witness.revision or file_revision(self.path.stat()) != self.witness.revision:
            raise RelationViolationError('Conversation source needs a current certificate.')

    def committed_sequence(self) -> int:
        """Global committed high-water; silent observations allocate no sequence."""
        self.require_open_prefix()
        return self.witness.through_seq

    def capture_sources(self, rows: tuple[WireSourcePointer[OriginalSource], ...]) -> Iterator[OriginalSource]:
        """Lend bounded original bytes, not this lock/connection, to decoding.

        The returned iterator owns only the original pointers, copied bytes and
        root selected by this certificate. It is a read snapshot, never a
        current publication/admission permit. Capture must finish in custody;
        decoding can finish after that custody has closed.
        """
        self.require_current()
        captured = tuple(((row, row.read_bytes(self.stream)) for row in rows))
        root_id = self.witness.root_id
        self.require_current()
        return (row.decode_bytes(raw, root_id) for row, raw in captured)

    def references(self, references) -> Iterator[CommittedDelivery]:
        """Capture exact seq/id originals through the existing sealed pointers."""
        marks = ','.join(('?' for _ in references))
        self.require_current()
        rows = DeliverySources.select(self.connection, where=f'seq IN ({marks})', parameters=tuple((ref.seq for ref in references)))
        by_sequence = {row.seq: row for row in rows}
        ordered = []
        for reference in references:
            row = by_sequence.get(reference.seq)
            if row is None or row.reference != reference:
                raise RelationViolationError('Notification reference is not its original source')
            ordered.append(row)
        return self.capture_sources(tuple(ordered))

    def delivery(self, seq: int) -> CommittedDelivery:
        """Resolve an exact source sequence through this original opened proof."""
        self.require_current()
        row = DeliverySources.one(self.connection, seq=seq)
        if row is None:
            raise RelationViolationError('No committed initial sideband for this wire sequence.')
        original, = self.capture_sources((row,))
        self.require_current()
        return original

    def addressed_page(self, bus: WireLog, request: AddressedPage, *, prefix: PrefixWitness | None=None):
        """Read a bounded original addressed window through this one certificate.

        The query carries no input/ACK authority. Capture resolves the page and
        addressed high-water through one current seal. Its decoder lends only
        the bounded original bytes; no connection or stream survives capture.
        """
        self.require_current()
        self.require_marker(bus._private_marker_unlocked())
        db, witness = (self.connection, self.witness)
        window = witness if prefix is None else prefix
        witness.require_read_window(window)
        try:
            rows = DeliverySources.read(db.execute(f"SELECT {','.join(('i.' + column for column in DeliverySources.columns()))} FROM {Addressed.declared_name} a JOIN {DeliverySources.declared_name} i ON i.seq=a.seq WHERE a.lookup=? AND i.seq>? AND i.seq<=? ORDER BY i.seq LIMIT ?", (request.lookup, request.after_seq, window.through_seq, request.limit + 1)))
            last = DeliverySources.read(db.execute(f'SELECT * FROM {DeliverySources.declared_name} ORDER BY seq DESC LIMIT 1'))
            latest = last[0].seq if last else 0
            if not 0 <= latest <= witness.through_seq:
                raise RelationViolationError('Certified initial high-water is invalid.')
            captured = self.capture_sources(tuple(rows[:request.limit]))
            self.require_current()
            self.require_marker(bus._private_marker_unlocked())

            def decoded():
                for original in captured:
                    if not any((r.recipient_lookup == request.lookup for r in original.audience.recipients)):
                        raise RelationViolationError('Certified initial lookup differs from bus row.')
                    yield original
            return (replace(witness, latest_source_seq=latest), decoded(), len(rows) > request.limit)
        except RelationViolationError:
            raise
        except (sqlite3.Error, OSError, ValueError, TypeError) as error:
            raise RelationViolationError('Certified initial page is unavailable.') from error

    def conversation_sources(self, lookup: str, predicate: str, parameters: tuple, *, limit: int, ascending: bool):
        """Read a bounded conversation from the existing certified source index.

        Sender and recipients come from the original frozen audience, never today's
        name binding. Capture holds the bus lock; decoding owns its bounded original bytes.
        This read cannot install or repair
        a checkpoint, grant delivery, or advance any native-input cursor.
        """
        self.require_current()
        db = self.connection
        rows = DeliverySources.read(db.execute(f"SELECT w.* FROM {DeliverySources.declared_name} w JOIN (SELECT seq FROM (SELECT w.seq FROM {DeliverySources.declared_name} w WHERE w.sender_lookup=? AND ({predicate}) ORDER BY w.seq {('ASC' if ascending else 'DESC')} LIMIT ?) UNION SELECT seq FROM (SELECT a.seq FROM {Addressed.declared_name} a JOIN {DeliverySources.declared_name} w ON w.seq=a.seq WHERE a.lookup=? AND ({predicate}) ORDER BY a.seq {('ASC' if ascending else 'DESC')} LIMIT ?)) membership ON membership.seq=w.seq ORDER BY w.seq {('ASC' if ascending else 'DESC')} LIMIT ?", (lookup, *parameters, limit, lookup, *parameters, limit, limit)))
        captured = self.capture_sources(tuple(rows))

        def decoded():
            for original in captured:
                if original.audience.sender_lookup != lookup and (not any((recipient.recipient_lookup == lookup for recipient in original.audience.recipients))):
                    raise RelationViolationError('Conversation index differs from frozen membership.')
                yield original
        return decoded()

    def context_manifests(self, incarnation: ThreadIncarnation, snapshot) -> Iterator[ContextManifest]:
        """Capture only original observations of this recorded incarnation.

        The index stores byte ranges and original owner identity, never manifest
        contents. Retained aliases select the same birth; a reused name cannot
        import another incarnation's observations. Wire order owns diff order.
        """
        self.require_current()
        storage = SqlStorage.for_type(ThreadIncarnation)
        parameters = tuple((storage.to_sql(FieldCodec.encode(recorded)) for recorded in incarnation.recorded_names(snapshot)))
        rows = tuple(ContextManifestSources.select(self.connection, where='thread IN (' + ','.join(('?' for _ in parameters)) + ')', parameters=parameters, order_by=('offset',)))
        captured = self.capture_sources(rows)

        def decoded():
            for manifest in captured:
                if manifest.thread.resolved(snapshot) != incarnation:
                    raise RelationViolationError('Context source differs from recorded owner.')
                yield manifest
        return decoded()

    def keyed_receipt(self, intent: PublicationIntents) -> Message | None:
        """The sealed key index filters absence; an original row proves presence."""
        self.require_current()
        if ResponseKeys.one(self.connection, key=intent.publication_key) is None:
            return None
        cursor = self.connection.execute(f'SELECT * FROM {DeliverySources.declared_name} WHERE message_id=? ORDER BY seq DESC', (intent.expected_message_id,))
        for row in DeliverySources.iterate(cursor):
            original = row.delivery(self.stream, self.witness.root_id)
            receipt = original.receipt
            if receipt is not None and receipt.publication_key == intent.publication_key:
                if receipt.execution_id != intent.execution_id:
                    raise RelationViolationError('Response publication identity conflicts.')
                if not intent.matches_publication(original.message):
                    raise RelationViolationError('Response publication intent conflicts.')
                self.require_current()
                return original.message
        raise RelationViolationError('Certified response key has no original source row.')

@dataclass(frozen=True)
class PrefixCertificate(CheckpointTable, TypedTable):
    """The existing SQLite row, decoded once at its persistence boundary."""
    singleton: Literal[1] = field(metadata={'sql': Column(primary_key=True)})
    version: Literal[2]
    root_id: str
    device: int
    inode: int
    offset: int
    through_seq: int
    digest: str
    tail: str
    mtime_ns: int
    ctime_ns: int

    def witness(self) -> PrefixWitness:
        return PrefixWitness(self.root_id, (self.device, self.inode, self.offset, self.mtime_ns, self.ctime_ns), self.through_seq, self.digest, self.tail)

    @classmethod
    def capture(cls, root_id: str, info: os.stat_result, seq: int, digest: bytes, tail: str) -> PrefixCertificate:
        return cls(1, 2, root_id, info.st_dev, info.st_ino, info.st_size, seq, digest.hex(), tail, info.st_mtime_ns, info.st_ctime_ns)

def _saved(db: sqlite3.Connection) -> PrefixWitness:
    schema = {name: sql for table in TypedTable.members_with(CheckpointTable) for name, sql in table.schema_objects().items()}
    actual = SQLiteSchemaObject.read(db.execute('SELECT name,sql FROM sqlite_master WHERE sql IS NOT NULL'))
    if {row.name: row.sql for row in actual} != schema:
        raise RelationViolationError('Private bus checkpoint schema is unavailable.')
    try:
        row = PrefixCertificate.one(db, singleton=1)
        if row is None:
            raise RelationViolationError('Private bus checkpoint certificate is missing.')
        return row.witness()
    except (TypeError, ValueError) as error:
        raise RelationViolationError('Private bus checkpoint identity is malformed.') from error

@contextmanager
def opened_private_checkpoint_unlocked(bus: WireLog, marker: WireMetadata):
    """Keep only this canonical lock's verified source/index resources open."""
    path = _path(bus.path)
    with ExitStack() as resources:
        try:
            db = resources.enter_context(closing(_connect(path)))
            stream = resources.enter_context(bus.path.open('rb'))
            saved = _verify_open_checkpoint_unlocked(bus, marker, db, stream, path)
            db.execute('PRAGMA query_only=ON')
        except (sqlite3.Error, OSError) as error:
            raise RelationViolationError('Private bus checkpoint verification is unavailable.') from error
        yield CertifiedSourceRead(bus.path, marker, db, stream, saved)

@contextmanager
def opened_claim_source_unlocked(bus: WireLog, private_marker: WireMetadata):
    """The existing claim durability owner supplies this lock's opened source."""
    with ExitStack() as resources:
        try:
            flags = os.O_RDONLY | getattr(os, 'O_NOFOLLOW', 0)
            try:
                descriptor = os.open(bus.path, flags)
            except FileNotFoundError:
                descriptor = None
            if descriptor is None and (certificate_enabled(bus.path) or private_marker.requires_checkpoint):
                raise RelationViolationError('Private checkpoint bus inode is missing.')
            source = None
            if descriptor is not None:
                stream = resources.enter_context(os.fdopen(descriptor, 'rb'))
                if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
                    raise RelationViolationError('Claim bus is not a regular file.')
                os.fsync(stream.fileno())
                if certificate_enabled(bus.path) or private_marker.requires_checkpoint:
                    private_marker = bus._private_marker_unlocked()
                    private_marker.seal
                    directory_fd = os.open(bus.path.parent, os.O_RDONLY | getattr(os, 'O_DIRECTORY', 0))
                    try:
                        os.fsync(directory_fd)
                    finally:
                        os.close(directory_fd)
                    source = resources.enter_context(opened_private_checkpoint_unlocked(bus, private_marker))
                else:
                    scan = WireScan(private_marker)
                    while (line := stream.readline(scan.max_row_bytes + 1)):
                        scan.read(line)
            if source is None:
                directory_fd = os.open(bus.path.parent, os.O_RDONLY | getattr(os, 'O_DIRECTORY', 0))
                try:
                    os.fsync(directory_fd)
                finally:
                    os.close(directory_fd)
        except OSError as error:
            raise RelationViolationError('Claim bus durability is UNKNOWN.') from error
        yield source

class ReadLedger(Sealed, LockedStore[ReadDocument]):
    filename = 'read_ledger.json'

    @property
    def record_type(self) -> type[ReadDocument]:
        return ReadDocument

    def empty(self) -> ReadDocument:
        return ReadDocument()

    @staticmethod
    def human(role: ThreadRole) -> bool:
        return not role.executable

    @staticmethod
    def bus_identity(path: Path) -> tuple[int, int] | None:
        try:
            info = path.stat()
        except FileNotFoundError:
            return None
        return (info.st_dev, info.st_ino)

    @staticmethod
    def conversation(message: Message, snapshot: RegistryProvenance) -> Conversation:
        from .channel_targets import BuiltinChannel, is_channel_target
        builtin = BuiltinChannel.lookup(message.target)
        if builtin is not None or is_channel_target(message.target):
            return Conversation(target=builtin.value if builtin is not None else message.target)
        names = sorted({snapshot.aliases.get(name, name) for name in (message.sender, message.target)})
        return Conversation(participants=tuple((ThreadIncarnation(name, snapshot.threads[name].created_at if name in snapshot.threads else -1.0) for name in names)))

    @staticmethod
    def _key(viewer: str, created_at: float, conversation: Conversation) -> str:
        return json.dumps([viewer, created_at, conversation.to_wire()], separators=(',', ':'))

    def capture(self, viewer: str, messages: Iterable[Message], snapshot: RegistrySnapshot, bus_path: Path, *, conversation_snapshot: RegistryProvenance | None=None) -> DisplayBasis:
        viewer = snapshot.aliases.get(viewer, viewer)
        grouped: dict[Conversation, list[int]] = {}
        for message in messages:
            conversation = self.conversation(message, conversation_snapshot or snapshot)
            grouped.setdefault(conversation, []).append(message.seq)
        return DisplayBasis(viewer, snapshot.threads[viewer].created_at, tuple((DisplayedConversation(conversation, tuple(sorted(set(sequences)))) for conversation, sequences in grouped.items())), self.bus_identity(bus_path))

    def mark_displayed(self, viewer: str, displayed: DisplayBasis) -> None:
        if displayed.bus_identity != self.bus_identity(self.path.with_name('bus.jsonl')):
            raise ValueError('Display bus changed; refresh the displayed page.')
        if viewer != displayed.viewer:
            raise ValueError('Display belongs to a different viewer.')

        def advance(document: ReadDocument) -> ReadDocument:
            messages = dict(document.messages) if document.bus_identity == displayed.bus_identity else {}
            for item in displayed.conversations:
                key = self._key(viewer, displayed.viewer_created_at, item.conversation)
                messages[key] = tuple(sorted(set(messages.get(key, ())) | set(item.sequences)))
            return replace(document, messages=messages, bus_identity=displayed.bus_identity) if messages != document.messages or document.bus_identity != displayed.bus_identity else document
        self.update(advance)

    def seen_sequences(self, viewer: str, snapshot: RegistrySnapshot, *, document: ReadDocument | None=None) -> frozenset[int]:
        viewer = snapshot.aliases.get(viewer, viewer)
        thread = snapshot.threads[viewer]
        seen: set[int] = set()
        document = self.read() if document is None else document
        if document.bus_identity != self.bus_identity(self.path.with_name('bus.jsonl')):
            return frozenset()
        for key, sequences in document.messages.items():
            name, created, raw = json.loads(key)
            if snapshot.aliases.get(name, name) == viewer and created == thread.created_at:
                conversation = Conversation.from_wire(raw)
                if conversation.current(snapshot):
                    seen.update(sequences)
        return frozenset(seen)

    def displayed_recipient(self, message, recipient, snapshot, *, document=None):
        """Return recorded human display evidence for this exact frozen recipient.

        Processing, assignment acceptance and a reply cannot grant this fact.
        A reused name with a different creation identity cannot inherit it.
        """
        from .bus_publication import stable_thread_lookup
        for thread in snapshot.threads.values():
            if self.human(thread.role) and stable_thread_lookup(thread.created_at) == recipient.recipient_lookup and (message.seq in self.seen_sequences(thread.name, snapshot, document=document)):
                return (thread.incarnation,)
        return ()

    @staticmethod
    def _transcript_key(viewer: str, source: str, inode: int) -> str:
        return json.dumps([viewer, str(Path(source).resolve()), inode])

    def transcript_seen(self, viewer: str, source: str, inode: int, *, document: ReadDocument | None=None) -> int:
        document = self.read() if document is None else document
        return document.transcripts.get(self._transcript_key(viewer, source, inode), 0)

    def mark_transcript(self, viewer: str, source: str, inode: int, through: int, size: int) -> None:
        key = self._transcript_key(viewer, source, inode)

        def advance(document: ReadDocument) -> ReadDocument:
            previous = document.transcripts.get(key, 0)
            if previous <= size and previous >= through:
                return document
            return replace(document, transcripts={**document.transcripts, key: through})
        self.update(advance)

@dataclass(frozen=True)
class AssignedTranscriptSource:
    root: Path
    recipient: ThreadIncarnation
    log: WireLog

    @classmethod
    def for_thread(cls, root, thread, log):
        return cls(root, thread.incarnation, log)

    def rows(self, predicate='1', parameters=(), *, limit=1, ascending=False):
        return self.log.conversation_sources(stable_thread_lookup(self.recipient.created_at), predicate, parameters, limit=limit, ascending=ascending)

    @property
    def frontier(self):
        return self.window()[0]

    def window(self, *, limit=1):
        """One certified original window owns both rows and its frontier."""
        rows = self.rows(limit=limit)
        return (AssignedSourceCursor(str(self.root), self.recipient, rows[0].message.seq if rows else 0), rows)

    def page_rows(self, traversal, sequence, through, *, limit):
        predicate, parameters = traversal.predicate(sequence, through)
        return self.rows(predicate, parameters, ascending=traversal.ascending, limit=limit)

    def native_records(self, fragments, routes, reader):
        """One original SQL read per bounded fragment, closed before wire/render."""
        from .native_runtime_input import NativeRuntimeInput
        lookup = stable_thread_lookup(self.recipient.created_at)
        for fragment in fragments:
            with NativeRuntimeInput._publication_read(self.root) as db:
                capture = partial(NativeRuntimeInput.transcript_projection, db, reader, owner_lookup=lookup)
                originals = tuple(((record, record.project(capture)) for record in fragment))
            for record, projection in originals:
                yield (record, record.project(lambda record: self.native_events(record, routes, *projection)))

    def native_events(self, record, routes, project_events, references):
        from .native_entries import TranscriptProjection
        entry = record.entry
        published = False
        routing = routes.get(entry.id)
        lookup = stable_thread_lookup(self.recipient.created_at)
        events = project_events(TranscriptProjection(routing, routes.input_display(entry.input_id)))
        if entry.final_reply:
            if routing is not None and routing.publications:
                marks = ','.join(('?' for _ in routing.publications))
                originals = self.rows(f'w.seq IN ({marks})', tuple((ref.seq for ref in routing.publications)), limit=len(routing.publications))
                published = all((any((original.message.reference == ref and original.audience.sender_lookup == lookup for original in originals)) for ref in routing.publications))
            if not published and references:
                marks = ','.join(('?' for _ in references))
                originals = self.rows(f'w.seq IN ({marks})', tuple((ref.seq for ref in references)), limit=len(references))
                published = all((any((original.message.reference == ref and original.audience.sender_lookup == lookup for original in originals)) for ref in references))
        result = []
        for event in events:
            if published and isinstance(event, AssistantTranscript):
                continue
            if isinstance(event, UserTranscript) and event.routed:
                requests = event.routing.requests
                marks = ','.join(('?' for _ in requests))
                originals = self.rows(f'w.seq IN ({marks})', tuple((reference.seq for reference in requests)), limit=len(requests))
                remaining = tuple((reference for reference in requests if not any((original.message.reference == reference for original in originals))))
                if not remaining:
                    continue
                event = replace(event, routing=TurnRouting(remaining, event.routing.reply))
            result.append(event)
        return tuple(result)

    def events(self, original):
        message = original.message
        if original.audience.sender_lookup == stable_thread_lookup(self.recipient.created_at):
            return (SentTranscript(message.body, timestamp=message.timestamp, source=message.reference, routing=TurnRouting(reply=MessageRoute(message.sender, (message.target,)))),)
        return (IncomingTranscript(message.body, timestamp=message.timestamp, source=message.reference, route=MessageRoute(message.sender, (message.target,)), routing=TurnRouting((message.reference,))),)

def conversation_sources(self, lookup, predicate, parameters, *, limit, ascending):
    """Read an original window through its existing canonical barrier."""
    with _store_lock(self.path) as lock:
        if not self.path.exists():
            return ()
        marker = self._private_marker_unlocked()
        source = lock.certified_read()
        source.require_marker(marker)
        originals = source.conversation_sources(lookup, predicate, parameters, limit=limit, ascending=ascending)
        source.require_current()
    return tuple(originals)

class WireAccess(DeclaredFamily, affix='Access'):

    @abstractmethod
    def require_append(self) -> None:
        ...

@dataclass(frozen=True)
class WritableAccess(WireAccess):

    def require_append(self) -> None:
        pass

@dataclass(frozen=True)
class ArchivedAccess(WireAccess):

    def require_append(self) -> None:
        raise RelationViolationError('Archived history is read-only.')

def read_original(root):
    bus = WireLog(Path(root) / 'bus.jsonl')
    with bus.certified_read() as source:
        return capture_original(bus, source)
